/**
 * Docusaurus conventions for `solv push`, detected from the content and
 * applied without a Docusaurus dependency. Every rule here is deterministic:
 * the same files always give the same documents.
 *
 * Sources, checked 2026-11-18:
 * - URLs, `id`, `slug`, index files: https://docusaurus.io/docs/create-doc
 *   and the plugin's `getSlug`:
 *   https://github.com/facebook/docusaurus/blob/main/packages/docusaurus-plugin-content-docs/src/slug.ts
 * - Number prefixes: https://docusaurus.io/docs/sidebar/autogenerated#using-number-prefixes
 *   and https://github.com/facebook/docusaurus/blob/main/packages/docusaurus-plugin-content-docs/src/numberPrefix.ts
 * - Category index files: https://github.com/facebook/docusaurus/blob/main/packages/docusaurus-plugin-content-docs/src/docs.ts
 * - Front matter keys: https://github.com/facebook/docusaurus/blob/main/packages/docusaurus-plugin-content-docs/src/frontMatter.ts
 * - Admonitions: https://docusaurus.io/docs/markdown-features/admonitions
 *   and https://github.com/facebook/docusaurus/blob/main/packages/docusaurus-mdx-loader/src/remark/admonitions/index.ts
 */

import { posix } from "node:path";

/**
 * Front matter keys only Docusaurus uses. `id`, `slug`, `title`,
 * `description`, `tags` and `keywords` are left out: other site generators
 * use them too, so they alone do not say a folder is Docusaurus.
 */
const DOCUSAURUS_KEYS = [
  "sidebar_label",
  "sidebar_position",
  "sidebar_class_name",
  "sidebar_key",
  "sidebar_custom_props",
  "displayed_sidebar",
  "hide_title",
  "hide_table_of_contents",
  "toc_min_heading_level",
  "toc_max_heading_level",
  "pagination_label",
  "pagination_next",
  "pagination_prev",
  "parse_number_prefixes",
  "custom_edit_url",
];
const DOCUSAURUS_KEY_RE = new RegExp(`^(?:${DOCUSAURUS_KEYS.join("|")})[ \\t]*:`, "m");

/** Docusaurus's default admonition keywords. */
const ADMONITION_TYPES = ["note", "tip", "info", "warning", "danger"];
const ADMONITION_OPEN_RE = new RegExp(
  `^([ \\t]*)(:{3,})(${ADMONITION_TYPES.join("|")})(?:\\[(.*)\\])?(?:[ \\t]+(.*?))?[ \\t]*\\r?$`,
);
const ADMONITION_CLOSE_RE = /^[ \t]*(:{3,})[ \t]*\r?$/;
// Imports of Docusaurus's own module aliases are a sure sign of a Docusaurus page.
const DOCUSAURUS_IMPORT_RE = /^import\s[^\n]*\bfrom\s+['"]@(?:theme|site|docusaurus)\//;
// MDX ESM: `import`/`export` statements at the start of a line.
const ESM_START_RE =
  /^(?:import\s+(?:['"]|[\w$*{])|export\s+(?:const|let|var|function|class|default|async|type|interface|\{|\*)(?![\w$]))/;

/** True when a front matter block uses a key only Docusaurus understands. */
export function hasDocusaurusFrontMatter(block: string | null): boolean {
  return block !== null && DOCUSAURUS_KEY_RE.test(block);
}

/** True when a body uses Docusaurus syntax: an admonition or a Docusaurus import. */
export function hasDocusaurusSyntax(body: string): boolean {
  return markLines(body).some(
    (line) =>
      !line.code && (ADMONITION_OPEN_RE.test(line.text) || DOCUSAURUS_IMPORT_RE.test(line.text)),
  );
}

// Dates (2021-11-foo) and versions (7.0-foo) are not number prefixes.
const IGNORED_PREFIX_RE = /^\d+[-_.]\d+/;
const NUMBER_PREFIX_RE = /^(\d+)\s*[-_.]+\s*([^-_.\s].*)$/;

/** `01-intro` -> `intro`, `003 - Guide` -> `Guide`; dates and versions unchanged. */
export function stripNumberPrefix(name: string): string {
  if (IGNORED_PREFIX_RE.test(name)) return name;
  return NUMBER_PREFIX_RE.exec(name)?.[2] ?? name;
}

/** Resolves a relative slug against a directory path ending in `/`, like a URL path. */
function resolvePathname(relative: string, dir: string): string {
  const segments = dir.split("/").filter((s) => s.length > 0);
  const parts = relative.split("/");
  for (const [index, part] of parts.entries()) {
    if (part === "..") segments.pop();
    else if (part !== "." && part !== "") segments.push(part);
    else if (part === "" && index === parts.length - 1 && segments.length > 0) {
      // A trailing slash is kept.
      return `/${segments.join("/")}/`;
    }
  }
  const last = parts[parts.length - 1];
  const trailing = (last === "." || last === "..") && segments.length > 0 ? "/" : "";
  return `/${segments.join("/")}${trailing}`;
}

/**
 * The URL path Docusaurus gives a doc, relative to the docs root (always
 * starting with `/`). `relPath` is the file's path under the docs folder
 * without its extension, with `/` separators.
 */
export function docusaurusSlug(relPath: string, frontMatter: { id?: string; slug?: string }) {
  const dirName = posix.dirname(relPath);
  const fileName = posix.basename(relPath);
  const strippedDir = dirName === "." ? "" : dirName.split("/").map(stripNumberPrefix).join("/");
  const dirSlug = strippedDir === "" ? "/" : `/${strippedDir}/`;

  const slug = frontMatter.slug;
  if (slug?.startsWith("/")) return slug;
  if (slug === undefined && isCategoryIndex(fileName, dirName)) return dirSlug;
  const baseId = frontMatter.id ?? stripNumberPrefix(fileName);
  return resolvePathname(slug ?? baseId, dirSlug);
}

/** `index`, `README` (any case) or a file named like its folder is the folder's page. */
function isCategoryIndex(fileName: string, dirName: string): boolean {
  const name = fileName.toLowerCase();
  const parent = dirName === "." ? "." : (dirName.split("/").pop() ?? "");
  return name === "index" || name === "readme" || name === parent.toLowerCase();
}

/** The doc's title fallback: its `id`, or the file name without a number prefix. */
export function docusaurusBaseId(relPath: string, frontMatter: { id?: string }): string {
  return frontMatter.id ?? stripNumberPrefix(posix.basename(relPath));
}

interface Line {
  text: string;
  code: boolean;
}

/**
 * Marks every line inside a fenced code block (fences included), so the
 * cleanup never changes a byte of code. An unclosed fence runs to the end,
 * as in CommonMark.
 */
function markLines(body: string): Line[] {
  const out: Line[] = [];
  let fence: { char: string; length: number } | null = null;
  for (const text of body.split("\n")) {
    const match = /^[ \t]*(`{3,}|~{3,})(.*)$/.exec(text.replace(/\r$/, ""));
    if (fence === null) {
      const delimiter = match?.[1];
      if (delimiter && !(delimiter[0] === "`" && (match?.[2] ?? "").includes("`"))) {
        fence = { char: delimiter[0] as string, length: delimiter.length };
        out.push({ text, code: true });
        continue;
      }
      out.push({ text, code: false });
      continue;
    }
    out.push({ text, code: true });
    const delimiter = match?.[1];
    if (
      delimiter &&
      delimiter[0] === fence.char &&
      delimiter.length >= fence.length &&
      (match?.[2] ?? "").trim() === ""
    ) {
      fence = null;
    }
  }
  return out;
}

function admonitionLabel(type: string, title: string | undefined): string {
  const label = title?.trim() || `${type[0]?.toUpperCase()}${type.slice(1)}`;
  return /[.:!?]$/.test(label) ? `**${label}**` : `**${label}:**`;
}

// A line that starts a paragraph, as opposed to a list, heading, quote, table,
// HTML or JSX, a directive, or an indented block.
function startsParagraph(text: string): boolean {
  return /^\S/.test(text) && !/^(?:[-*+]\s|\d+[.)]\s|#|>|\||<|:::|`{3}|~{3})/.test(text);
}

/**
 * Turns admonitions into labelled paragraphs: `:::tip[Title]` (or the older
 * `:::tip Title`) becomes `**Title:**` and `:::note` becomes `**Note:**`,
 * joined to the first line of the content when that starts a paragraph and
 * on its own line otherwise. Closing `:::` lines are dropped.
 */
function convertAdmonitions(lines: Line[]): Line[] {
  const out: Line[] = [];
  const open: number[] = [];
  let pendingLabel: { indent: string; label: string } | null = null;

  for (const line of lines) {
    if (pendingLabel !== null) {
      if (!line.code && line.text.trim() === "") continue;
      const { indent, label } = pendingLabel;
      pendingLabel = null;
      if (!line.code && startsParagraph(line.text.trimStart())) {
        out.push({ text: `${indent}${label} ${line.text.trimStart()}`, code: false });
        continue;
      }
      out.push({ text: `${indent}${label}`, code: false }, { text: "", code: false });
    }
    if (line.code) {
      out.push(line);
      continue;
    }
    const opening = ADMONITION_OPEN_RE.exec(line.text);
    if (opening) {
      open.push((opening[2] as string).length);
      pendingLabel = {
        indent: opening[1] ?? "",
        label: admonitionLabel(opening[3] as string, opening[4] ?? opening[5]),
      };
      out.push({ text: "", code: false });
      continue;
    }
    const closing = ADMONITION_CLOSE_RE.exec(line.text);
    if (closing && open.length > 0 && open[open.length - 1] === (closing[1] as string).length) {
      open.pop();
      out.push({ text: "", code: false });
      continue;
    }
    out.push(line);
  }
  if (pendingLabel !== null)
    out.push({ text: `${pendingLabel.indent}${pendingLabel.label}`, code: false });
  return out;
}

/** Drops MDX `import`/`export` blocks; in MDX one runs until a blank line. */
function dropEsm(lines: Line[]): Line[] {
  const out: Line[] = [];
  let inEsm = false;
  for (const line of lines) {
    if (inEsm) {
      if (line.code || line.text.trim() !== "") continue;
      inEsm = false;
    }
    if (!line.code && ESM_START_RE.test(line.text)) {
      inEsm = true;
      continue;
    }
    out.push(line);
  }
  return out;
}

/**
 * Finds the end of a JSX tag starting at `start` (`<`), honouring quoted
 * attribute values and `{...}` expressions. Returns the index after `>`, or
 * -1 when the text is not a complete tag.
 */
function tagEnd(text: string, start: number): number {
  let depth = 0;
  let quote: string | null = null;
  for (let i = start + 1; i < text.length; i++) {
    const ch = text[i] as string;
    if (quote !== null) {
      if (ch === "\\" && depth > 0) i++;
      else if (ch === quote) quote = null;
      continue;
    }
    if (ch === '"' || ch === "'" || (ch === "`" && depth > 0)) quote = ch;
    else if (ch === "{") depth++;
    else if (ch === "}") depth = Math.max(0, depth - 1);
    else if (ch === ">" && depth === 0) return i + 1;
    else if (ch === "<" && depth === 0) return -1;
  }
  return -1;
}

// A component tag: `<Tabs`, `</TabItem`, `<Foo.Bar`, or a fragment `<>`/`</>`.
const COMPONENT_TAG_RE = /^<\/?(?:[A-Z][\w$]*(?:\.[\w$]+)*(?=[\s/>])|>)/;

/**
 * Removes JSX component tags from a run of non-code lines, keeping what is
 * between an opening and a closing tag. Self-closing components have no text
 * and disappear. Lower-case HTML tags and inline code spans are left alone.
 */
function stripComponents(text: string): string {
  let out = "";
  let i = 0;
  while (i < text.length) {
    const ch = text[i] as string;
    if (ch === "`") {
      let run = 1;
      while (text[i + run] === "`") run++;
      const fence = "`".repeat(run);
      const close = text.indexOf(fence, i + run);
      if (close !== -1 && text[close + run] !== "`") {
        out += text.slice(i, close + run);
        i = close + run;
        continue;
      }
      out += fence;
      i += run;
      continue;
    }
    if (ch === "<" && COMPONENT_TAG_RE.test(text.slice(i, i + 200))) {
      const end = tagEnd(text, i);
      if (end !== -1) {
        i = end;
        continue;
      }
    }
    out += ch;
    i++;
  }
  return out;
}

function stripComponentLines(lines: Line[]): Line[] {
  const out: Line[] = [];
  let run: string[] = [];
  const flush = () => {
    if (run.length === 0) return;
    const before = run;
    const after = stripComponents(before.join("\n")).split("\n");
    for (const [index, text] of after.entries()) {
      // A line that only held tags becomes blank rather than stray spaces.
      const blanked = text.trim() === "" ? "" : text;
      const changed = blanked !== before[index];
      out.push({ text: changed ? blanked.replace(/[ \t]+(\r?)$/, "$1") : blanked, code: false });
    }
    run = [];
  };
  for (const line of lines) {
    if (line.code) {
      flush();
      out.push(line);
    } else {
      run.push(line.text);
    }
  }
  flush();
  return out;
}

/** Collapses runs of blank lines outside code and trims blank lines at both ends. */
function tidyBlankLines(lines: Line[]): string {
  const out: string[] = [];
  let blank = false;
  for (const line of lines) {
    const isBlank = !line.code && line.text.trim() === "";
    if (isBlank) {
      blank = out.length > 0;
      continue;
    }
    if (blank) out.push("");
    blank = false;
    out.push(line.text);
  }
  return out.length === 0 ? "" : `${out.join("\n")}\n`;
}

/**
 * Cleans a Docusaurus/MDX body into plain Markdown: admonitions become
 * labelled paragraphs, `import`/`export` lines go, JSX components are replaced
 * by their text content (or dropped when they have none), and fenced code
 * blocks are kept byte for byte.
 */
export function cleanDocusaurusMarkdown(body: string): string {
  const lines = stripComponentLines(dropEsm(convertAdmonitions(markLines(body))));
  return tidyBlankLines(lines);
}

/**
 * Puts the front matter `description` at the top of the document: after a
 * leading `# Heading` when there is one, else first.
 */
export function withDescription(markdown: string, description: string | undefined): string {
  if (description === undefined || description.trim() === "") return markdown;
  const text = description.trim();
  const heading = /^(#[ \t][^\n]*\n)\n*/.exec(markdown);
  if (heading) {
    return `${heading[1]}\n${text}\n\n${markdown.slice(heading[0].length)}`;
  }
  return markdown === "" ? `${text}\n` : `${text}\n\n${markdown}`;
}
